import{_ as i,o as e,c as t,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Infernalis (Day 1) -- Ceph Plugins","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- Ceph Plugins","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph","分布式存储","插件系统","集成测试","版本控制","C++接口","C接口"],"categories":["会议纪要","Ceph插件开发"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_Ceph_Plugins.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_Ceph_Plugins.md","lastUpdated":1780459816000}'),n={name:"posts/2015/CDS_Infernalis_Day_1_--_Ceph_Plugins.md"};function a(_,l,p,r,o,C){return e(),t("div",null,[...l[0]||(l[0]=[s("<p>在2023年11月X日举行的Ceph会议上，与会人员讨论了在Ceph中添加私有键值存储作为可插拔模块，并讨论了插件安装和升级的一般支持。</p><p><strong>会议关键细节</strong>：</p><ul><li>Ceph目前有两个插件系统：CLS插件系统和Azure代码插件系统。</li><li>SanDisk希望创建一个新的对象存储键值存储抽象，该抽象能够加载实现此抽象的插件，但可能不包含在Ceph中。</li><li>插件集成测试对于确保插件与现有集群兼容至关重要。</li><li>插件应以操作系统包的形式分发，并使用标准分发工具进行安装和升级。</li><li>插件版本字符串应与OSD版本严格匹配，以确保兼容性。</li><li>需要一个机制，使OSD和Monitor能够同意一个插件白名单。</li><li>插件接口应以C++虚拟类形式定义，以便动态加载和实现。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li>如何简化插件集成测试过程。</li><li>如何使用标准分发工具分发插件，并确保其兼容性和稳定性。</li><li>是否需要放松插件版本字符串与OSD版本匹配的要求。</li><li>如何实现一个通用的插件加载机制。</li><li>是否使用C++虚拟类定义插件接口，以及如何处理C++接口的兼容性问题。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>将讨论如何简化插件集成测试过程。</li><li>将使用标准分发工具分发插件，并确保其兼容性和稳定性。</li><li>将继续使用严格匹配的插件版本字符串与OSD版本。</li><li>将讨论如何实现一个通用的插件加载机制。</li><li>将使用C++虚拟类定义插件接口，并考虑使用C接口作为中间层。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Luik将更新Pad笔记，并提供更多关于通用插件系统实现方案的详细信息。</li><li>Team将讨论如何简化插件集成测试过程。</li><li>Team将研究如何使用标准分发工具分发插件，并确保其兼容性和稳定性。</li><li>Team将讨论如何实现一个通用的插件加载机制。</li><li>Team将讨论如何处理C++接口的兼容性问题。</li></ul><p><strong>改进点</strong>：</p><ul><li>在总结中更详细地描述了Ceph现有的插件系统和新的插件系统。</li><li>强调了插件集成测试的重要性。</li><li>详细说明了插件分发和版本控制的要求。</li><li>对插件加载机制和接口进行了深入讨论。</li><li>提供了后续行动计划的具体内容。</li></ul>",11)])])}const D=i(n,[["render",a]]);export{g as __pageData,D as default};
